3819:             return Ok((start, 0));
3820:         }
3821:         let mut statement = self.db.prepare_cached(
3822:             "WITH RECURSIVE ancestry(id,parent,ordinal) AS (
3823:                  SELECT id,parent,0 FROM blocks WHERE id=?1 AND id!=?2
3824:                  UNION ALL
3825:                  SELECT b.id,b.parent,a.ordinal+1
3826:                  FROM ancestry a JOIN blocks b ON b.id=a.parent
3827:                  WHERE b.id!=?2 LIMIT ?3
3828:              )
3829:              SELECT b.parent,b.height,b.chainwork,b.state_root,substr(b.packet,1,?4),
